// Original synthesized cues. No downloads; the app unlocks audio from a user gesture.
const CUES={castAir:[460,990,.22,.021],castFire:[180,75,.20,.025],castNature:[115,230,.24,.027],castWater:[680,290,.25,.021],select:[420,510,.07,.018],pair:[520,780,.18,.030],place:[240,410,.12,.035],repair:[310,620,.18,.03],deliver:[380,570,.16,.025],wrong:[180,145,.14,.018],coin:[880,1175,.12,.018],impact:[105,55,.16,.045],jump:[220,340,.14,.018],land:[95,48,.13,.03],reward:[523,1046,.38,.035],step:[130,70,.065,.012]};
export class GameAudio{
 constructor(){this.context=null;this.wind=null;this.voices=0;this.last=new Map();this.lastPosition=null;this.distance=0;this.stage='ground';this.reading=false;this.muted=false;this.bus=null;}
 attach(context){if(this.context===context)return;this.context=context;this.bus=context.createGain();this.bus.gain.value=this.muted?0:1;this.bus.connect(context.destination);}
 setMuted(value){this.muted=!!value;if(this.bus)this.bus.gain.setTargetAtTime(this.muted?0:1,this.context.currentTime,.025);if(this.muted)this.silence();}
 play(kind='place',variant=0){const c=this.context;if(this.muted||!c||c.state==='suspended'||this.voices>=16)return false;const now=c.currentTime;if(now-(this.last.get(kind)??-1)<(kind==='step'?.16:.055))return false;this.last.set(kind,now);const [a,b,duration,volume]=CUES[kind]||CUES.place,o=c.createOscillator(),g=c.createGain();o.type=['step','impact','land','place'].includes(kind)?'triangle':'sine';const pitch=kind==='step'?1+(variant%3)*.18:1;o.frequency.setValueAtTime(a*pitch,now);o.frequency.exponentialRampToValueAtTime(b*pitch,now+duration);g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(volume*(this.reading?.25:1),now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g).connect(this.bus);this.voices++;o.onended=()=>{o.disconnect();g.disconnect();this.voices--;};o.start(now);o.stop(now+duration+.02);return true;}
 ambience(active,area=0){const c=this.context;if(!c)return;if(!this.wind&&active&&c.state==='running'){const source=c.createBufferSource(),buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),data=buffer.getChannelData(0);let n=41;for(let i=0;i<data.length;i++){n=(Math.imul(n,1664525)+1013904223)>>>0;data[i]=(n/4294967296*2-1)*.35;}source.buffer=buffer;source.loop=true;const filter=c.createBiquadFilter(),gain=c.createGain();filter.type='lowpass';filter.frequency.value=360;gain.gain.value=0;source.connect(filter).connect(gain).connect(this.bus);source.start();this.wind={source,filter,gain};}if(this.wind){this.wind.filter.frequency.setTargetAtTime([340,600,430][area]||340,c.currentTime,.4);this.wind.gain.gain.setTargetAtTime(active?(this.reading?.002:.012):0,c.currentTime,.12);}}
 frame({position,height=1,moving=false,grounded=true,stage='ground',area=0,active=false}={}){this.ambience(active,area);if(!position)return;const old=this.lastPosition;this.lastPosition={x:position.x,z:position.z};if(active&&old&&moving&&grounded){const d=Math.hypot(position.x-old.x,position.z-old.z);if(d<.5){this.distance+=d;if(this.distance>.30+height*.19){this.play('step',area);this.distance=0;}}}else this.distance=0;if(active&&stage==='landing'&&this.stage==='air')this.play('land',area);if(active&&stage==='anticipation'&&this.stage==='ground')this.play('jump');this.stage=stage;}
 silence(){this.ambience(false);}
}
